import numpy as np
from scipy.optimize import minimize

def equations(vars):
    x, y, z = vars
    eq1 = x**2 + y**2 + z**2 - 3
    eq2 = x*y**3 + y*z**3 + z*x**3 - 3
    return eq1**2 + eq2**2

def find_solutions():
    solutions = []
    # Try different starting points
    for i in range(10):
        for j in range(10):
            for k in range(10):
                start_point = np.random.uniform(-2, 2, 3)
                res = minimize(equations, start_point)
                if res.fun < 1e-7:
                    sol = np.round(res.x, 6)
                    # Check if it's a new solution
                    is_new = True
                    for s in solutions:
                        if np.allclose(sol, s, atol=1e-4):
                            is_new = False
                            break
                    if is_new:
                        solutions.append(sol)
    return solutions

print(find_solutions())

import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z = vars
    return -(x*y**3 + y*z**3 + z*x**3)

def constraint(vars):
    x, y, z = vars
    return x**2 + y**2 + z**2 - 3

cons = {'type': 'eq', 'fun': constraint}

max_val = -float('inf')
best_sol = None

for _ in range(100):
    start_point = np.random.uniform(-2, 2, 3)
    res = minimize(objective, start_point, constraints=cons)
    if res.success:
        if -res.fun > max_val:
            max_val = -res.fun
            best_sol = res.x

print(f"Max value: {max_val}, Best sol: {best_sol}")

